fn choose_odd(v: &Vec<u64>) -> usize {
    // Find the position of an element `x` such that `x` is odd.
    // Since it's guaranteed there's at least one odd element, `.unwrap()`
    // will never panic in a valid input.
    v.iter()
     .position(|&x| x & 1 == 1)
     .unwrap()
}

